import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Navbar = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [showMobileMenu, setShowMobileMenu] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const navigate = useNavigate();

  const syncAuthState = () => {
    const isLogged = localStorage.getItem('isLoggedIn') === 'true';
    const role = localStorage.getItem('role');
    const token = localStorage.getItem('token');
    if (isLogged && token) {
      setIsLoggedIn(true);
      setUserRole(role);
    } else {
      setIsLoggedIn(false);
      setUserRole(null);
    }
  };

  useEffect(() => {
    syncAuthState();

    // Listen for auth changes in the same tab (dispatched by Login/Logout)
    window.addEventListener('authChanged', syncAuthState);
    // Listen for auth changes from other tabs
    window.addEventListener('storage', syncAuthState);

    // Close dropdown when clicking outside
    const handleClickOutside = (event) => {
      if (!event.target.closest('.dropdown')) {
        setShowDropdown(false);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => {
      window.removeEventListener('authChanged', syncAuthState);
      window.removeEventListener('storage', syncAuthState);
      document.removeEventListener('click', handleClickOutside);
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.setItem('isLoggedIn', 'false');
    localStorage.removeItem('role');
    setIsLoggedIn(false);
    setUserRole(null);
    // Notify other components in the same tab
    window.dispatchEvent(new Event('authChanged'));
    navigate('/');
  };


  return (
    <header className="bg-white shadow-sm" style={{ position: 'sticky', top: 0, zIndex: 1000 }}>
      <div className="container">
        <nav className="navbar navbar-expand-lg navbar-light py-3">
          {/* Brand Logo - Matching your screenshot */}
          <Link to="/" className="navbar-brand fw-bold" style={{ fontSize: '1.8rem', color: '#333' }}>
            Enjoy<span style={{ color: '#007bff' }}>Drive</span>
          </Link>

          {/* Mobile Menu Toggle */}
          <button
            className="navbar-toggler border-0"
            type="button"
            onClick={(e) => {
              e.preventDefault();
              setShowMobileMenu(!showMobileMenu);
            }}
            aria-expanded={showMobileMenu}
            aria-controls="navbarNav"
          >
            <span className="navbar-toggler-icon"></span>
          </button>

          {/* Navigation Menu - Matching your screenshot */}
          <div className={`collapse navbar-collapse ${showMobileMenu ? 'show' : ''}`} id="navbarNav">
            <ul className="navbar-nav mx-auto">
              <li className="nav-item">
                <Link to="/" className="nav-link fw-semibold text-dark px-3">
                  Home
                </Link>
              </li>
              <li className="nav-item">
                <a
                  href="#collection"
                  className="nav-link fw-semibold text-dark px-3"
                  onClick={(e) => {
                    e.preventDefault();
                    const element = document.getElementById('collection');
                    if (element) {
                      element.scrollIntoView({ behavior: 'smooth' });
                    }
                  }}
                >
                  Collection
                </a>
              </li>
              <li className="nav-item">
                <a
                  href="#testimonials"
                  className="nav-link fw-semibold text-dark px-3"
                  onClick={(e) => {
                    e.preventDefault();
                    const element = document.getElementById('testimonials');
                    if (element) {
                      element.scrollIntoView({ behavior: 'smooth' });
                    }
                  }}
                >
                  Testimonials
                </a>
              </li>
              <li className="nav-item">
                <a
                  href="#contact"
                  className="nav-link fw-semibold text-dark px-3"
                  onClick={(e) => {
                    e.preventDefault();
                    const element = document.getElementById('contact');
                    if (element) {
                      element.scrollIntoView({ behavior: 'smooth' });
                    }
                  }}
                >
                  Contact
                </a>
              </li>
            </ul>

            {/* Auth Buttons - Matching your screenshot exactly */}
            <div className="d-flex align-items-center gap-2">
              {isLoggedIn ? (
                <>
                  {userRole === 'admin' && (
                    <button
                      onClick={() => navigate('/admin')}
                      className="btn text-white fw-semibold px-4 py-2"
                      style={{
                        backgroundColor: '#28a745',
                        border: 'none',
                        borderRadius: '5px',
                        fontSize: '14px'
                      }}
                    >
                      ADMIN
                    </button>
                  )}
                  <Link
                    to="/bookings"
                    className="btn btn-outline-primary fw-semibold px-4 py-2"
                    style={{ borderRadius: '5px', fontSize: '14px' }}
                  >
                    MY BOOKINGS
                  </Link>
                  <button
                    onClick={handleLogout}
                    className="btn text-white fw-semibold px-4 py-2"
                    style={{
                      backgroundColor: '#dc3545',
                      border: 'none',
                      borderRadius: '5px',
                      fontSize: '14px'
                    }}
                  >
                    LOGOUT
                  </button>
                </>
              ) : (
                <>
                  {/* LOGIN Button */}
                  <Link
                    to="/login"
                    className="btn text-white fw-semibold px-4 py-2 me-2"
                    style={{
                      backgroundColor: '#007bff',
                      border: 'none',
                      borderRadius: '5px',
                      fontSize: '14px',
                      textDecoration: 'none'
                    }}
                  >
                    LOGIN
                  </Link>
                </>
              )}

            </div>
          </div>
        </nav>
      </div>
    </header>
  );
};

export default Navbar;
